#include <stdio.h>

typedef struct {
    long long x, y;
} Point;

long long dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

long long cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

Point vec(Point a, Point b) {
    Point res = {b.x - a.x, b.y - a.y};
    return res;
}

long long dist_sq(Point a, Point b) {
    long long dx = b.x - a.x;
    long long dy = b.y - a.y;
    return dx * dx + dy * dy;
}

int main(void) {
    Point p[8]; // índices de 1 a 7

    for (int i = 1; i <= 7; i++) {
        if (scanf("%lld %lld", &p[i].x, &p[i].y) != 2) {
            return 0;
        }
    }

    // Condição 1: Ângulo ∠P2P1P3 é agudo (vértice em P1)
    Point p1p2 = vec(p[1], p[2]);
    Point p1p3 = vec(p[1], p[3]);
    if (dot(p1p2, p1p3) <= 0) {
        printf("N\n");
        return 0;
    }

    // Condição 2: Segmentos P1P2 e P1P3 têm o mesmo comprimento
    if (dist_sq(p[1], p[2]) != dist_sq(p[1], p[3])) {
        printf("N\n");
        return 0;
    }

    // Condição 3: Pontos P2, P3, P4 e P5 são colineares
    Point p2p3 = vec(p[2], p[3]);
    Point p2p4 = vec(p[2], p[4]);
    Point p2p5 = vec(p[2], p[5]);
    if (cross(p2p3, p2p4) != 0 || cross(p2p3, p2p5) != 0) {
        printf("N\n");
        return 0;
    }

    // Condição 4: Pontos médios dos segmentos P2P3 e P4P5 são coincidentes
    if (p[2].x + p[3].x != p[4].x + p[5].x || p[2].y + p[3].y != p[4].y + p[5].y) {
        printf("N\n");
        return 0;
    }

    // Condição 5: Segmento P2P3 tem comprimento maior que o segmento P4P5
    if (dist_sq(p[2], p[3]) <= dist_sq(p[4], p[5])) {
        printf("N\n");
        return 0;
    }

    // Condição 6: Segmentos P4P6 e P5P7 são perpendiculares ao segmento P2P3
    Point p4p6 = vec(p[4], p[6]);
    Point p5p7 = vec(p[5], p[7]);
    if (dot(p4p6, p2p3) != 0 || dot(p5p7, p2p3) != 0) {
        printf("N\n");
        return 0;
    }

    // Condição 7: Segmentos P4P6 e P5P7 têm o mesmo comprimento
    if (dist_sq(p[4], p[6]) != dist_sq(p[5], p[7])) {
        printf("N\n");
        return 0;
    }

    // Condição 8: Pontos P1 e P6 devem estar separados pela reta que contém P2P3
    Point p2p1 = vec(p[2], p[1]);
    Point p2p6 = vec(p[2], p[6]);
    long long cp1 = cross(p2p3, p2p1);
    long long cp6 = cross(p2p3, p2p6);

    if (cp1 == 0 || cp6 == 0 || !((cp1 > 0 && cp6 < 0) || (cp1 < 0 && cp6 > 0))) {
        printf("N\n");
        return 0;
    }

    printf("S\n");
    return 0;
}
